command:
// Get all tokens currently targeted
const targets = game.user.targets;

if (targets.size === 0) {
  ui.notifications.warn("Please target at least one token!");
} else {
  // Create and execute the roll
  const damageRoll = await new Roll("1d20!").evaluate();
  const cumRoll = await new Roll("6d12!").evaluate();

  // Show the roll in chat so players see the result
  let content = `<div class="dice-roll"><div class="dice-result">`;
  content += `<div style="margin-bottom: 4px;  font-size: 14px;">`
  content += `</div> <div style="margin-bottom: 8px;  font-size: 12px;"> </div>`;
  content += `<div style="display: flex; flex-direction: row; flex-wrap: wrap; gap: 4px; justify-content: space-between;">`;
  content += `
  <div style="flex: 1; max-width: 90px; text-align: center; border: 1px solid #777; border-radius: 3px; 
  padding: 4px; background: rgba(0,0,0,0.05);">
  <div style="font-size: 0.7em; text-transform: uppercase; 
  font-weight: bold; border-bottom: 1px solid #777; margin-bottom: 4px;"> Impregnation </div>
  <div class="dice-total" style="border:none; background:none; padding:0; line-height: 1;"> ${damageRoll.total} </div>
  </div>`;
  content += `
  <div style="flex: 1; max-width: 90px; text-align: center; border: 1px solid #777; border-radius: 3px; 
  padding: 4px; background: rgba(0,0,0,0.05);">
  <div style="font-size: 0.7em; text-transform: uppercase; 
  font-weight: bold; border-bottom: 1px solid #777; margin-bottom: 4px;"> CUM ml </div>
  <div class="dice-total" style="border:none; background:none; padding:0; line-height: 1;"> ${cumRoll.total} </div>
  </div>`;
  content += `</div></div></div>`;

  for (let token of targets) {
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ token: this.actor }),
      content: content,
    });
  }


}
